import * as React from "react";
import { useState, useEffect }from "react";
import MenuBlock from "../menuBlock/MenuBlock";
import TopNavItem, { TopNavItemProps } from "../topNav/TopNavItem";
import Button from "../button/Button";
import IconButton from "../iconButton/IconButton";
import SearchBar from "../topNav/SearchBar";
import { MpaIcon } from "../icon/MpaIcon";
import { SvgMpaIcon,SvgMpaLogo } from "../../assets/icons";
import { MpaLogo } from "../logo/MpaLogo";

export interface TopItemBlockProps {
    navItems: {
        name?: string;
        header?: string;
        desc?: string,
        link?: string,
        menuItems: {
          name: string;
          leadingIcon?: keyof typeof SvgMpaIcon | string;    
          showDivider?: boolean;
          disabled?: boolean;
          subMenuItems?: TopNavItemProps["navItem"]["menuItems"];
        }[];
    }[];

    layout?: "menu-block" | "mega-menu" | "mega-menu-2" ;
    showSearch?: boolean;
    colour: "primary" | "secondary" | "tertiary";    
    /** Logo icon name or path */
    logo? : keyof typeof SvgMpaLogo | string;
}


const TopItemBlock: React.FC<TopItemBlockProps> = ({ logo= "MpaWhiteLogo", navItems, layout, showSearch ,  colour = "primary",  }) => {

    const [openIndex, setOpenIndex] = React.useState<number | null>(null);
    const [isSearchVisible, setSearchVisible] = useState(false);

    const [windowWidth, setWindowWidth] = useState(window.innerWidth);

    const showSearchBar = () => {
        setSearchVisible(!isSearchVisible); 
  
        if (!isSearchVisible) {
          setOpenIndex(null); // Close the menu when the search bar is shown
        }
    };

    const searchBoxClass = `${isSearchVisible ? 'show' : 'hide'}`;
    const isMobile = windowWidth < 768;


    const handleToggleMenu = (index: number) => {
        if (openIndex === index) {
          setOpenIndex(null);
        } else {
          setOpenIndex(index);
        }
    };

    const renderIcon = () => {
        if (windowWidth < 768) { 
            return isSearchVisible ? "X" : "Menu2";
        }
        return isSearchVisible ? "X" : "Search";
    };

    useEffect(() => {
        const handleResize = () => {
            setWindowWidth(window.innerWidth);
        };

        // Add event listener for resizing
        window.addEventListener('resize', handleResize);

        // Cleanup the event listener when the component is unmounted
        return () => {
            window.removeEventListener('resize', handleResize);
        };
    }, []); 


    
    return (
       
        <>
        <div className="main-top-nav">
            <div className="logo-container">
                <MpaLogo logoName={logo} width={60} height={60}/>
            </div>

            {!isMobile &&(
                <div className={`top-nav ${colour}`}>
                    {navItems.map((navItem, index) => (
                    <div key={index} className="nav-item-container">
                        <div className={`top-nav-item ${openIndex === index && searchBoxClass === 'hide' ? 'open' : ''}`}>
                        <div className="nav-item-content" onClick={() => handleToggleMenu(index)}>
                            <TopNavItem navItem={navItem} index={index} openIndex={openIndex}/> 
                        </div>
                        </div> 

                        {layout == "menu-block" && (
                        navItem.menuItems && openIndex === index && searchBoxClass === 'hide' &&(
                            <div className="menu-block-item">
                            <MenuBlock menuItems={navItem.menuItems} colour={colour} />
                            </div>
                        )
                        )} 
                    </div>
                    ))}
                </div>
            )}

            <div className="auth-container">
                <Button id={"buttonId"} leadingIcon={"Lock"} label="Login"></Button>
            </div>

            <div className="search-container">
                {showSearch && (
                <IconButton 
                    id={"iconButtonId"}
                    className={`icon-btn icon-btn-square icon-btn-${colour}`} 
                    icon={renderIcon()}
                    btnType={"standard"}
                    onClick={showSearchBar}
                >
                </IconButton>
                )}
            </div>
        </div>   
                         
        <SearchBar className={`search-box ${searchBoxClass}`} buttonClassName={`icon-btn icon-btn-square icon-btn-${colour}`}/>
    
        </>
                
      );

};

export default TopItemBlock;
